// Match Catalog: parses Gemini JSON and matches against your Catalog sheet
const base = $('Normalize Message').first().json;
const aiRaw = $('AI Read Request').first().json;
const catalog = $input.all().map(i => i.json);

let parsed = { is_prescription: base.is_photo, readable: true, medicines: [], other: 'empty' };
try {
  const rawText = aiRaw?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (err) {
  parsed = { is_prescription: base.is_photo, readable: false, medicines: [], other: 'parse_error' };
}

const requested = Array.isArray(parsed.medicines) ? parsed.medicines : [];
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]+/g, ' ').trim();
const expiresAt = new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString();

if (base.is_photo && parsed.readable === false) {
  const line = {
    res_id: base.request_id,
    created_at: base.received_at,
    customer_id: base.customer_phone,
    wa_phone_id: base.phone_number_id,
    customer_name: base.customer_name,
    sku: 'MANUAL_REVIEW',
    name: 'Needs Pharmacist Review',
    strength: 'unclear',
    qty: 1,
    unit_price: 0,
    total_egp: 0,
    available_stock: 0,
    controlled: true,
    status: 'pending_pharmacist',
    expires_at: expiresAt,
    pharmacist: '',
    note: 'Blurry/unreadable prescription photo'
  };
  return [{
    json: {
      ...base,
      parsed,
      route: 'needs_pharmacist',
      matched_lines: [line],
      total_price: 0,
      reply_text: '',
      pharmacist_summary: `⚠️ Unreadable prescription photo from ${base.customer_name} (${base.customer_phone}).\nRequest ID: ${base.request_id}\nPlease review and approve/reject.`
    }
  }];
}

if (requested.length === 0) {
  let reply = 'Welcome to Dawaa Pharmacy! Please send the medicine name (with strength and quantity) or a clear photo of your prescription, and we will check availability for you.';
  if (parsed.other === 'question') {
    reply = 'Thank you for messaging Dawaa Pharmacy. Please send the medicine name or a clear prescription photo so we can check stock and reserve it for you.';
  } else if (base.is_photo && parsed.is_prescription === false) {
    reply = 'We could not recognize a prescription or medicine box in that image. Please send a clear photo of the prescription or type the medicine name.';
  }
  return [{
    json: {
      ...base,
      parsed,
      route: 'nothing_found',
      matched_lines: [],
      total_price: 0,
      reply_text: reply,
      pharmacist_summary: ''
    }
  }];
}

const matchedLines = [];
let needsPharmacist = Boolean(base.is_photo || parsed.is_prescription);
let anyCatalogMatch = false;

requested.forEach((med) => {
  const reqName = String(med.name || 'unclear').trim();
  const reqStrength = String(med.strength || 'unclear').trim();
  const qty = Math.max(1, parseInt(med.qty, 10) || 1);
  const reqNorm = norm(reqName);

  const nameMatches = (reqNorm && reqNorm !== 'unclear')
    ? catalog.filter(row => {
        const candidates = [row.name, row.active_ingredient]
          .filter(Boolean)
          .flatMap(v => String(v).split(/[,/]+/))
          .map(norm)
          .filter(Boolean);
        return candidates.some(c => c.includes(reqNorm) || reqNorm.includes(c));
      })
    : [];

  let best = null;
  if (nameMatches.length > 0) {
    if (reqStrength && norm(reqStrength) !== 'unclear') {
      best = nameMatches.find(row =>
        norm(row.strength).includes(norm(reqStrength)) || norm(reqStrength).includes(norm(row.strength))
      ) || nameMatches[0];
    } else {
      best = nameMatches[0];
    }
  }

  if (best) {
    anyCatalogMatch = true;
    const stock = Number(best.stock || 0);
    const price = Number(best.price_egp || 0);
    const controlled = ['true', 'yes', '1'].includes(String(best.controlled || '').toLowerCase());
    const ambiguousStrength = reqStrength.toLowerCase() === 'unclear' && nameMatches.length > 1;

    const reasons = [];
    if (controlled) reasons.push('Controlled drug');
    if (stock < qty) reasons.push(`Low stock (avail: ${stock})`);
    if (ambiguousStrength) reasons.push('Multiple strengths');
    if (base.is_photo || parsed.is_prescription) reasons.push('Prescription photo');

    if (reasons.length > 0) needsPharmacist = true;

    matchedLines.push({
      res_id: base.request_id,
      created_at: base.received_at,
      customer_id: base.customer_phone,
      wa_phone_id: base.phone_number_id,
      customer_name: base.customer_name,
      sku: String(best.sku || ''),
      name: String(best.name || reqName),
      strength: String(best.strength || reqStrength),
      qty,
      unit_price: price,
      total_egp: price * qty,
      available_stock: stock,
      controlled,
      status: 'pending_pharmacist',
      expires_at: expiresAt,
      pharmacist: '',
      note: reasons.length > 0 ? reasons.join('; ') : 'Auto-reserved'
    });
  } else {
    needsPharmacist = true;
    matchedLines.push({
      res_id: base.request_id,
      created_at: base.received_at,
      customer_id: base.customer_phone,
      wa_phone_id: base.phone_number_id,
      customer_name: base.customer_name,
      sku: 'UNMATCHED',
      name: reqName,
      strength: reqStrength,
      qty,
      unit_price: 0,
      total_egp: 0,
      available_stock: 0,
      controlled: true,
      status: 'pending_pharmacist',
      expires_at: expiresAt,
      pharmacist: '',
      note: 'Not found in catalog'
    });
  }
});

if (!base.is_photo && !anyCatalogMatch) {
  const names = requested.map(m => m.name).filter(Boolean).join(', ');
  return [{
    json: {
      ...base,
      parsed,
      route: 'nothing_found',
      matched_lines: [],
      total_price: 0,
      reply_text: `Sorry, we could not find "${names}" in our current pharmacy catalog. Please double-check the spelling or send a photo of the box/prescription.`,
      pharmacist_summary: ''
    }
  }];
}

const finalRoute = needsPharmacist ? 'needs_pharmacist' : 'auto_reserve';
matchedLines.forEach(line => {
  line.status = finalRoute === 'needs_pharmacist' ? 'pending_pharmacist' : 'reserved';
});

const totalPrice = matchedLines.reduce((sum, l) => sum + l.total_egp, 0);
const summaryLines = matchedLines.map(
  (l, i) => `${i + 1}. ${l.name} (${l.strength}) x${l.qty} — Stock: ${l.available_stock} | Controlled: ${l.controlled ? 'Yes' : 'No'} | ${l.note}`
).join('\n');

const pharmacistSummary = [
  `🩺 *New Pharmacy Request (${base.request_id})*`,
  `Customer: ${base.customer_name} (${base.customer_phone})`,
  `Type: ${base.is_photo ? 'Prescription Photo' : 'Text Request'}`,
  '',
  '*Items:*',
  summaryLines,
  '',
  `Est. Total: ${totalPrice} EGP`
].join('\n');

return [{
  json: {
    ...base,
    parsed,
    route: finalRoute,
    matched_lines: matchedLines,
    total_price: totalPrice,
    reply_text: '',
    pharmacist_summary: pharmacistSummary
  }
}];

// One Row per Medicine: expands matched_lines so Google Sheets appends one row per medicine
const data = $input.first().json;
const lines = Array.isArray(data.matched_lines) ? data.matched_lines : [];
return lines.map(line => ({
  json: {
    ...line,
    route: data.route
  }
}));

// Take Stock Now: prepares Catalog stock decrements for auto-reserved items
const matched = $('Match Catalog').first().json.matched_lines || [];
const bySku = new Map();

for (const line of matched) {
  if (!line.sku || line.sku === 'UNMATCHED' || line.sku === 'MANUAL_REVIEW') continue;
  const prev = bySku.get(line.sku) || { sku: line.sku, available_stock: Number(line.available_stock || 0), qty: 0 };
  prev.qty += Number(line.qty || 1);
  bySku.set(line.sku, prev);
}

return Array.from(bySku.values()).map(entry => ({
  json: {
    sku: entry.sku,
    stock: Math.max(0, entry.available_stock - entry.qty)
  }
}));

// Parse Decision: extracts pharmacist Approve/Reject callback data from Telegram
const cb = $input.first().json.callback_query;
if (!cb || !cb.data) return [];

const [rawAction, requestId] = String(cb.data).split(':');
const action = rawAction === 'approve' ? 'approved' : (rawAction === 'reject' ? 'rejected' : '');
if (!action || !requestId) return [];

const user = cb.from || {};
const pharmacistName = [user.first_name, user.last_name].filter(Boolean).join(' ') || user.username || 'Pharmacist';

return [{
  json: {
    callback_query_id: cb.id,
    action,
    request_id: requestId,
    chat_id: cb.message?.chat?.id || '',
    message_id: cb.message?.message_id || '',
    original_text: cb.message?.text || '',
    pharmacist_name: pharmacistName,
    decided_at: new Date().toISOString()
  }
}];

// Apply Decision: validates pending lines and catalog stock using your exact Reservations schema
const decision = $('Parse Decision').first().json;
const allReservations = $('Find Pending Lines').all().map(i => i.json);
const catalog = $input.all().map(i => i.json);

const pendingLines = allReservations.filter(
  r => String(r.res_id || '').trim() === String(decision.request_id).trim()
    && String(r.status || '').trim() === 'pending_pharmacist'
);

if (pendingLines.length === 0) {
  return [{
    json: {
      ...decision,
      decision_ok: false,
      callback_answer: 'This request was already processed or has no pending items.',
      line_updates: [],
      stock_updates: [],
      customer_phone: '',
      customer_name: '',
      updated_telegram_text: decision.original_text,
      customer_message: ''
    }
  }];
}

const catalogMap = new Map(catalog.map(c => [String(c.sku), c]));
const stockTotals = new Map();
const stockUpdates = [];

if (decision.action === 'approved') {
  for (const line of pendingLines) {
    const sku = String(line.sku || '');
    if (!sku || sku === 'UNMATCHED' || sku === 'MANUAL_REVIEW') continue;
    const qty = Number(line.qty || 1);
    stockTotals.set(sku, (stockTotals.get(sku) || 0) + qty);
  }

  for (const [sku, neededQty] of stockTotals.entries()) {
    const item = catalogMap.get(sku);
    const currentStock = Number(item?.stock || 0);
    if (!item || currentStock < neededQty) {
      return [{
        json: {
          ...decision,
          decision_ok: false,
          callback_answer: `Insufficient stock for SKU ${sku} (available: ${currentStock}, needed: ${neededQty}).`,
          line_updates: [],
          stock_updates: [],
          customer_phone: String(pendingLines[0].customer_id || pendingLines[0].wa_phone_id || ''),
          customer_name: String(pendingLines[0].customer_name || 'Customer'),
          updated_telegram_text: decision.original_text,
          customer_message: ''
        }
      }];
    }
    stockUpdates.push({
      sku,
      stock: Math.max(0, currentStock - neededQty)
    });
  }
}

const lineUpdates = pendingLines.map(line => ({
  row_number: line.row_number,
  res_id: line.res_id,
  status: decision.action,
  pharmacist: decision.pharmacist_name,
  note: `${decision.action} at ${decision.decided_at}`
}));

const customerPhone = String(pendingLines[0].customer_id || pendingLines[0].wa_phone_id || '');
const customerName = String(pendingLines[0].customer_name || 'Customer');
const totalPrice = pendingLines.reduce((sum, l) => sum + Number(l.total_egp || 0), 0);
const itemSummary = pendingLines
  .map(l => `• ${l.name || l.sku} x${l.qty}`)
  .join('\n');

const statusStamp = decision.action === 'approved'
  ? `\n\n✅ APPROVED by ${decision.pharmacist_name} at ${decision.decided_at}`
  : `\n\n❌ REJECTED by ${decision.pharmacist_name} at ${decision.decided_at}`;

const customerMessage = decision.action === 'approved'
  ? `Hello ${customerName}, your pharmacy reservation (${decision.request_id}) has been approved by our pharmacist!\n\nReserved items:\n${itemSummary}\n\nEstimated Total: ${totalPrice} EGP\nPlease show your Request ID at pickup.`
  : `Hello ${customerName}, regarding your request (${decision.request_id}): our pharmacist could not fulfill this reservation right now (item unavailable or requires an in-person consultation). Please reply or visit the pharmacy for alternatives.`;

return [{
  json: {
    ...decision,
    decision_ok: true,
    callback_answer: decision.action === 'approved' ? 'Reservation approved & customer notified.' : 'Request rejected & customer notified.',
    line_updates: lineUpdates,
    stock_updates: stockUpdates,
    customer_phone: customerPhone,
    customer_name: customerName,
    total_price: totalPrice,
    updated_telegram_text: `${decision.original_text}${statusStamp}`,
    customer_message: customerMessage
  }
}];

// Line Updates: expands line_updates into one item per reservation row
const lines = $('Apply Decision').first().json.line_updates || [];
return lines.map(l => ({ json: l }));

// Stock Rows: expands stock_updates into one item per catalog SKU
const rows = $('Apply Decision').first().json.stock_updates || [];
return rows.map(r => ({ json: r }));
